import * as React from "react";

export type MoonFullIconProps = React.SVGProps<SVGSVGElement> & { size?: number };

export function MoonFullIcon({ size = 20, ...props }: MoonFullIconProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.8"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      {...props}
    >
      <circle cx="12" cy="12" r="7.5"/><circle cx="10" cy="10.5" r="1.2"/><circle cx="13.5" cy="13.5" r="1.6"/>
    </svg>
  );
}
